entries[168370] = { ["name"] = "Rusted Keys to the Junkheap Drifter", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Junkheap Drifter.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When you really want to be noticed... and don't mind strapping yourself to a giant, barely-held-together wheel.\"\nDrop:\nRustfeather\nZone:\nMechagon" }
