entries[168399] = { ["name"] = "Fetish of the Dark Caverns", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Anima of Life and Death.\nMajor Power:\nAnima of Death\nInstant 2.5 min cooldown Draw upon your vitality to sear your foes, dealing 10% of your maximum health in Fire damage to all nearby enemies and heal for 5% of your maximum health per enemy hit, up to 25% of your maximum health.\nMinor Power:\nAnima of Life\nAzerite energy courses through your veins, increasing maximum health by 244 every 5 sec, stacking up to 10 times.\n\nThis effect is lost if you fall below 35% health." }
entries[168400] = { ["name"] = "Null Force Containment Unit", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Nullification Dynamo.\nRequires Friendly reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nMajor Power:\nEmpowered Null Barrier\nInstant 3 min cooldown Gain an empowered Null Barrier, absorbing [ 11391 * (1 + Versatility)] magic damage for 10 sec .\nMinor Power:\nNull Barrier\nEvery 20 sec, gain a Null Barrier, absorbing [ 2268 * (1 + Versatility)] magic damage for 10 sec.\n\"It looks completely void of energy and matter, yet the unit is clearly heavier than the containment unit itself.\"" }
