entries[168408] = { ["name"] = "Child of Torcali", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"This daughter of the great direhorn loa, Torcali, never lost faith that her keeper would help her grow to her full potential.\"\nQuest:\nWander Not Alone\nZone:\nZuldazar" }
