entries[168436] = { ["name"] = "Focused Star Point", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Spirit of Preservation.\nMajor Power:\nSpirit of Preservation\n40 yd range Channeled (3 sec cast) 1 min cooldown Channel a beam of energy onto an ally, healing them for [( 1452 * (5) + 1452 ) * (1 + Versatility)] over 3 sec.\nMinor Power:\nDevout Spirit\nEvery 5 sec, gain Devout Spirit, causing your next Quick Heal to heal for an additional 153 , stacking up to 3 times.\n\nUnique: Corruption Resistance increased by 10." }
entries[168439] = { ["name"] = "Swirling Star Dust", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Spirit of Preservation.\nMajor Power:\nSpirit of Preservation\n40 yd range Channeled (3 sec cast) 1 min cooldown Channel a beam of energy onto an ally, healing them for [( 1452 * (5) + 1452 ) * (1 + Versatility)] over 3 sec. Up to 6 other allies in the beam are healed for [ 145 * (1 + Versatility)] every 0.6 sec.\nMinor Power:\nDevout Spirit\nEvery 5 sec, gain Devout Spirit, causing your next Quick Heal to heal for an additional 153 , stacking up to 5 times.\n\nUnique: Corruption Resistance increased by 10." }
entries[168440] = { ["name"] = "Gleaming Star Shard", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Spirit of Preservation.\nLearn any Rank 3 Rajani or Uldum Accord essence on another character to unlock this essence.\nRequires you to be Revered with the Rajani. (Cannot purchase if already known.)\nMajor Power:\nSpirit of Preservation\n40 yd range Channeled (3 sec cast) 1 min cooldown Channel a beam of energy onto an ally, healing them for [( 1452 * (5) + 1452 ) * (1 + Versatility)] over 3 sec. Up to 6 other allies in the beam are healed for [ 145 * (1 + Versatility)] every 0.6 sec.\n\nEach time Spirit of Preservation heals the primary target, gain a stack of Devout Spirit.\nMinor Power:\nDevout Spirit\nEvery 5 sec, gain Devout Spirit, causing your next Quick Heal to heal for an additional 153 , stacking up to 5 times.\n\nEach stack of Devout Spirit consumed increases the critical strike chance of your next Quick Heal within 15 sec by 20%.\n\nUnique: Corruption Resistance increased by 10." }
entries[168442] = { ["name"] = "Roiling Blood of the Vanquished", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Blood of the Enemy.\nMajor Power:\nBlood of the Enemy\nInstant 2 min cooldown The Heart of Azeroth erupts violently, dealing 1739 Shadow damage to enemies within 12 yds. You gain 25% critical strike chance against the targets for 10 sec .\nMinor Power:\nBlood-Soaked\nYour critical strikes with spells and abilities grant a stack of Blood-Soaked . Upon reaching 40 stacks, you gain 125 Haste for 8 sec." }
entries[168443] = { ["name"] = "Agitated Blood of the Dominated", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Blood of the Enemy.\nRequires the achievement \"Battlefield Brawler\". (Cannot purchase if already known.)\nMajor Power:\nBlood of the Enemy\nInstant 1.5 min cooldown The Heart of Azeroth erupts violently, dealing 1739 Shadow damage to enemies within 12 yds. You gain 25% critical strike chance against the targets for 10 sec.\nMinor Power:\nBlood-Soaked\nYour critical strikes with spells and abilities grant a stack of Blood-Soaked. Upon reaching 40 stacks, you gain 125 Haste for 8 sec.\n\nEach stack of Blood-Soaked grants 2 Critical Strike." }
entries[168444] = { ["name"] = "Churning Blood of the Conquered", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Blood of the Enemy.\nRequires the achievement \"Battlefield Tactician\". (Cannot purchase if already known.)\nLearn Rank 3 Blood of the Enemy, Artifice of Time, or Sphere of Suppression on another character to unlock this essence.\nMajor Power:\nBlood of the Enemy\nInstant 1.5 min cooldown The Heart of Azeroth erupts violently, dealing 1739 Shadow damage to enemies within 12 yds. You gain 25% critical strike chance against the targets for 10 sec, and increases your critical hit damage by 25% for 5 sec.\nMinor Power:\nBlood-Soaked\nYour critical strikes with spells and abilities grant a stack of Blood-Soaked, increasing Critical Strike by 2 . Upon reaching 40 stacks, you gain 125 Haste for 8 sec.\n\nBlood-Soaked has a 25% chance of only consuming 30 stacks." }
