entries[168533] = { ["name"] = "Schematic: Ub3r-Module: P.O.G.O.", ["text"] = "Binds when picked up\nUse: Teaches you how to craft an Ub3r-Module: P.O.G.O.\nCreate an Ub3r-Module: P.O.G.O.\nRequires Kul Tiran Engineering (150)\nRequires Rustbolt Resistance\n- Revered\n\nUb3r Module: P.O.G.O\nBinds when picked up\nUnique\nUse: Guarantees your Ub3r Inventions to be a P.O.G.O.\nRequires Kul Tiran Engineering (50)\nRequires Monelite Ore (5), Storm Silver Ore (2), Insulated Wiring (15), Chemical Blasting Cap (10)" }
