entries[168536] = { ["name"] = "Recrystallizing Azerite Formation", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Azeroth's Undying Gift.\nMajor Power:\nAzeroth's Undying Gift\nInstant 45 sec cooldown Reduce all damage you take by 20% for 4 sec.\nMinor Power:\nHardened Azerite\nWhen you fall below 35% health, gain 799 Armor for 8 sec.\n\nThis effect may occur once every 120 sec. (2.5m cooldown)" }
entries[168537] = { ["name"] = "Tempered Azerite Formation", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Azeroth's Undying Gift.\nLearn Rank 3 Condensed Life-Force, Vitality Conduit, or Azeroth's Undying Gift on another character to unlock this essence.\nMajor Power:\nAzeroth's Undying Gift\nInstant 45 sec cooldown Reduce all damage you take by 40% for 2 sec, then 20% for the next 2 sec.\nMinor Power:\nHardened Azerite\nWhen you fall below 35% health, gain ( 799 * 200 / 100) Armor for 4 sec, then 799 Armor for the next 4 sec.\n\nThis effect may occur once every 120 sec. (2.5m cooldown)" }
entries[168538] = { ["name"] = "Dazzling Azerite Formation", ["text"] = "Rank 4\nBinds when picked up\nUnique\nClasses: Warrior , Paladin , Death Knight , Monk , Druid , Demon Hunter\nUse: Infuse your Heart of Azeroth with Azeroth's Undying Gift.\nMajor Power:\nAzeroth's Undying Gift\nInstant 45 sec cooldown Reduce all damage you take by 40% for 2 sec, then 20% for the next 2 sec.\nMinor Power:\nHardened Azerite\nWhen you fall below 35% health, gain ( 799 * 200 / 100) Armor for 4 sec, then 799 Armor for the next 4 sec.\n\nThis effect may occur once every 120 sec. (2.5m cooldown)" }
