entries[168558] = { ["name"] = "Fetish of the Deep Dungeons", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Anima of Life and Death.\nMajor Power:\nAnima of Death\nInstant 2 min cooldown Draw upon your vitality to sear your foes, dealing 10% of your maximum health in Fire damage to all nearby enemies and heal for 5% of your maximum health per enemy hit, up to 25% of your maximum health.\nMinor Power:\nAnima of Life\nAzerite energy courses through your veins, increasing maximum health by 244 every 5 sec, stacking up to 10 times.\n\nGain a stack of Anima of Life when you kill an enemy that yields experience or honor.\n\nThis effect is lost if you fall below 35% health." }
entries[168559] = { ["name"] = "Fetish of the Hidden Labyrinths", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Anima of Life and Death.\nLearn Rank 3 Focusing Iris, Life-Binder's Invocation, or Anima of Life and Death on another character to unlock this essence.\nMajor Power:\nAnima of Death\nInstant 2 min cooldown Draw upon your vitality to sear your foes, dealing 10% of your maximum health in Fire damage to all nearby enemies and heal for 10% of your maximum health per enemy hit, up to 50% of your maximum health.\nMinor Power:\nAnima of Life\nAzerite energy courses through your veins, increasing maximum health by 244 every 5 sec, stacking up to 10 times. While at maximum stacks, heal for 185 health every 5 sec.\n\nGain a stack of Anima of Life when you kill an enemy that yields experience or honor.\n\nThis effect is lost if you fall below 35% health." }
entries[168560] = { ["name"] = "Fetish of the Gilded Catacombs", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Anima of Life and Death.\nMajor Power:\nAnima of Death\nInstant 2 min cooldown Draw upon your vitality to sear your foes, dealing 10% of your maximum health in Fire damage to all nearby enemies and heal for 10% of your maximum health per enemy hit, up to 50% of your maximum health.\nMinor Power:\nAnima of Life\nAzerite energy courses through your veins, increasing maximum health by 244 every 5 sec, stacking up to 10 times. While at maximum stacks, heal for 185 health every 5 sec.\n\nGain a stack of Anima of Life when you kill an enemy that yields experience or honor.\n\nThis effect is lost if you fall below 35% health." }
entries[168566] = { ["name"] = "Null Force Cooling Unit", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Nullification Dynamo.\nRequires Honored reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nMajor Power:\nEmpowered Null Barrier\nInstant 2.25 min cooldown Gain an empowered Null Barrier, absorbing [ 11391 * (1 + Versatility)] magic damage for 10 sec.\nMinor Power:\nNull Barrier\nEvery 15 sec, gain a Null Barrier, absorbing the next [ 2268 * (1 + Versatility)] magic damage you take for 10 sec." }
entries[168568] = { ["name"] = "Null Force Nullifier", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Nullification Dynamo.\nRequires Revered reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nLearn any Rank 3 Rustbolt Resistance essence on another character to unlock this essence.\nMajor Power:\nEmpowered Null Barrier\nInstant 2.25 min cooldown Gain an empowered Null Barrier, absorbing [ 11391 * (1 + Versatility)] magic damage for 10 sec, and instantly remove all harmful Magic, Curse, Poison, and Disease effects on you.\nMinor Power:\nNull Barrier\nEvery 15 sec, gain a Null Barrier, absorbing the next [ 2268 * (1 + Versatility)] magic damage you take for 10 sec.\n\nWhen Null Barrier expires, it implodes, dealing Shadow damage equal to the total amount absorbed, divided among all nearby enemies." }
entries[168569] = { ["name"] = "Null Force Visualizer", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Nullification Dynamo.\nMajor Power:\nEmpowered Null Barrier\nInstant 2.25 min cooldown Gain an empowered Null Barrier, absorbing [ 11391 * (1 + Versatility)] magic damage for 10 sec, and instantly remove all harmful Magic, Curse, Poison, and Disease effects on you.\nMinor Power:\nNull Barrier\nEvery 15 sec, gain a Null Barrier, absorbing the next [ 2268 * (1 + Versatility)] magic damage you take for 10 sec.\n\nWhen Null Barrier expires, it implodes, dealing Shadow damage equal to the total amount absorbed, divided among all nearby enemies." }
entries[168573] = { ["name"] = "Death-Resistant Leaf", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Touch of the Everlasting.\nMajor Power:\nTouch of the Everlasting\nYour next death is prevented, and you instead regenerate to 20% of your maximum health and take 85% reduced damage for 3 sec.\n\nCannot occur more often than once per 10 min.\nMinor Power:\nWill to Survive\nWhen you fall below 35% health, gain 55 Avoidance for 15 sec, and your next Active Mitigation will last 30% longer . This can only occur once every 1.5 min.\n\nUnique: Corruption Resistance increased by 10.\n\"Flourishes in the wind.\"" }
entries[168574] = { ["name"] = "Petrified Living Bark", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Touch of the Everlasting.\nMajor Power:\nTouch of the Everlasting\nYour next death is prevented, and you instead regenerate to 40% of your maximum health and take 85% reduced damage for 3 sec.\n\nCannot occur more often than once per 10 min.\nMinor Power:\nWill to Survive\nWhen you fall below 35% health, gain 55 Avoidance for 15 sec, and your next Active Mitigation will last 30% longer . This can only occur once every 60 sec.\n\nUnique: Corruption Resistance increased by 10." }
entries[168575] = { ["name"] = "Branch of Rejuvenating Rings", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Touch of the Everlasting.\nLearn any Rank 3 Rajani or Uldum Accord essence on another character to unlock this essence.\nRequires you to be Revered with the Rajani. (Cannot purchase if already known.)\nMajor Power:\nTouch of the Everlasting\nYour next death is prevented, and you instead regenerate to 40% of your maximum health and take 85% reduced damage for 3 sec.\n\nWhen your death is prevented, the cooldown of Shield Wall is reset.\n\nCannot occur more often than once per 10 min.\nMinor Power:\nWill to Survive\nWhen you fall below 35% health, gain 55 Avoidance for 15 sec, and your next Active Mitigation will last 50% longer . This can only occur once every 60 sec.\n\nUnique: Corruption Resistance increased by 10." }
entries[168576] = { ["name"] = "Roots of Magnificent Revival", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Touch of the Everlasting.\nMajor Power:\nTouch of the Everlasting\nYour next death is prevented, and you instead regenerate to 40% of your maximum health and take 85% reduced damage for 3 sec.\n\nWhen your death is prevented, the cooldown of Shield Wall is reset.\n\nCannot occur more often than once per 10 min.\nMinor Power:\nWill to Survive\nWhen you fall below 35% health, gain 55 Avoidance for 15 sec, and your next Active Mitigation will last 50% longer . This can only occur once every 60 sec.\n\nUnique: Corruption Resistance increased by 10." }
entries[168577] = { ["name"] = "Imbued Pearl", ["text"] = "Quest Item\n\"Energy flickers within.\"" }
entries[168578] = { ["name"] = "Sphere of Suppressed Force", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Sphere of Suppression.\nMajor Power:\nSuppressing Pulse\nInstant 1 min cooldown Unleash a heavy pulse of suppressive energy, reducing the movement speed of all enemies within 15 yds by 70% and reducing their attack speed by 25% for 8 sec.\nMinor Power:\nSphere of Suppression\nUnlimited range When an enemy melee attacks you, their movement speed is reduced by 30% and you gain 64 Haste for 5 sec." }
entries[168579] = { ["name"] = "Sphere of Unrestrained Fury", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Sphere of Suppression.\nRequires the achievement \"Battlefield Brawler\". (Cannot purchase if already known.)\nMajor Power:\nSuppressing Pulse\nInstant 45 sec cooldown Unleash a heavy pulse of suppressive energy, reducing the movement speed of all enemies within 15 yds by 70% and reducing their attack speed by 25% for 8 sec.\nMinor Power:\nSphere of Suppression\nUnlimited range When an enemy melee attacks you, their movement speed is reduced by 30% and you gain 64 Haste for 7 sec ." }
entries[168580] = { ["name"] = "Sphere of Leeched Mobility", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Sphere of Suppression.\nRequires the achievement \"Battlefield Tactician\". (Cannot purchase if already known.)\nLearn Rank 3 Blood of the Enemy, Artifice of Time, or Sphere of Suppression on another character to unlock this essence.\nMajor Power:\nSuppressing Pulse\nInstant 45 sec cooldown Unleash a heavy pulse of suppressive energy, reducing the movement speed of all enemies within 15 yds by 70% and reducing their attack speed by 25% for 8 sec.\n\nIf you hit an enemy, gain 50% movement speed for 8 sec.\nMinor Power:\nSphere of Suppression\nUnlimited range When an enemy melee attacks you, their movement speed is reduced by 30% and you gain 64 Haste and Speed for 7 sec ." }
entries[168581] = { ["name"] = "Sphere of Incandescent Neutralization", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Sphere of Suppression.\nMajor Power:\nSuppressing Pulse\nInstant 45 sec cooldown Unleash a heavy pulse of suppressive energy, reducing the movement speed of all enemies within 15 yds by 70% and reducing their attack speed by 25% for 8 sec.\n\nIf you hit an enemy, gain 50% movement speed for 8 sec.\nMinor Power:\nSphere of Suppression\nUnlimited range When an enemy melee attacks you, their movement speed is reduced by 30% and you gain 64 Haste and Speed for 7 sec ." }
