entries[168611] = { ["name"] = "Petrified Ebony Scale", ["text"] = "Rank 1\nQuest Item\nUnique\nUse: Infuse your Heart of Azeroth with The Crucible of Flame.\nMajor Power:\nConcentrated Flame\n40 yd range Instant 30 sec cooldown 1 Charge Blast your target with a ball of concentrated flame, dealing [ 824 * (1 + Versatility)] Fire damage to an enemy or healing an ally for [ 824 * (1 + Versatility)] .\n\nEach cast of Concentrated Flame deals 100% increased damage or healing. This bonus resets after every third cast.\nMinor Power:\nAncient Flame\nApproximately 3 procs per minute Your spells and abilities have a chance to cauterize your target for ( 351 * 5) Fire damage over 10 sec or to heal an ally for ( 351 * 5) over 10 sec .\n\"Embodying the earth itself, this ancient scale has been tempered with ebony fire.\"" }
entries[168612] = { ["name"] = "Dreamglow Dragonscale", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Crucible of Flame.\nMajor Power:\nConcentrated Flame\n40 yd range Instant 30 sec cooldown 1 Charge Blast your target with a ball of concentrated flame, dealing [ 824 * (1 + Versatility)] Fire damage to an enemy or healing an ally for [ 824 * (1 + Versatility)], then burn the target for an additional 75% of the damage or healing done over 6 sec.\n\nEach cast of Concentrated Flame deals 100% increased damage or healing. This bonus resets after every third cast.\nMinor Power:\nAncient Flame\nApproximately 1.25 procs per minute Your spells and abilities have a chance to cauterize your target for [source value] Fire damage over 10 sec or to heal an ally for [source value] over 10 sec.\n\"The restored scale radiates the glow of the Emerald Dream and the essence of the Green flight.\"", ["unresolvedValues"] = true }
entries[168613] = { ["name"] = "Tempered Scale of the Scarlet Broodmother", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Crucible of Flame.\nLearn Rank 3 Crucible of Flame on another character to unlock this essence.\nMajor Power:\nConcentrated Flame\n40 yd range Instant 30 sec cooldown 1 Charge Blast your target with a ball of concentrated flame, dealing [ 824 * (1 + Versatility)] Fire damage to an enemy or healing an ally for [ 824 * (1 + Versatility)], then burn the target for an additional 75% of the damage or healing done over 6 sec.\n\nEach cast of Concentrated Flame deals 100% increased damage or healing. This bonus resets after every third cast.\nMax 2 Charges.\nMinor Power:\nAncient Flame\nApproximately 1.25 procs per minute Your spells and abilities have a chance to cauterize your target for [source value] Fire damage over 10 sec or to heal an ally for [source value] over 10 sec, stacking up to 3 times.\n\"Brimming with life energy, the flames of the Life-Binder flicker and dance along the scale.\"", ["unresolvedValues"] = true }
entries[168614] = { ["name"] = "Charged Scale of the Blue Aspect", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Crucible of Flame.\nMajor Power:\nConcentrated Flame\n40 yd range Instant 30 sec cooldown 1 Charge Blast your target with a ball of concentrated flame, dealing [ 824 * (1 + Versatility)] Fire damage to an enemy or healing an ally for [ 824 * (1 + Versatility)], then burn the target for an additional 75% of the damage or healing done over 6 sec.\n\nEach cast of Concentrated Flame deals 100% increased damage or healing. This bonus resets after every third cast.\nMax 2 Charges.\nMinor Power:\nAncient Flame\nApproximately 1.25 procs per minute Your spells and abilities have a chance to cauterize your target for [source value] Fire damage over 10 sec or to heal an ally for [source value] over 10 sec, stacking up to 3 times.\n\"Crackling blue magic sparks around the scale in embodiment of the once great Aspect.\"", ["unresolvedValues"] = true }
entries[168615] = { ["name"] = "Volatile Worldvein", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Worldvein Resonance.\nMajor Power:\nWorldvein Resonance\nInstant 1 min cooldown Concentrate energy into the Heart of Azeroth, immediately causing 2 Lifeblood Shards to erupt from the nearby ground for 12 sec, and incease the primary stat gained from Lifeblood Shards by 300% for 18 sec.\n\nLifeblood Shard\nGrants you and any other ally using Worldvein Resonance 13 primary stat while within 8 yds of the Lifeblood Shard. You can benefit from a maximum of 4 Lifeblood Shards at a time.\nMinor Power:\nLifeblood\nEvery 18-25 sec, a Lifeblood Shard erupts from the nearby ground for 12 sec.\n\nLifeblood Shard\nGrants you and any other ally using Worldvein Resonance 13 primary stat while within 12 yds of the Lifeblood Shard. You can benefit from a maximum of 4 Lifeblood Shards at a time.\n\"The Worldvein is budding with an energy drawing Azerite to it, bolstering whomever wields it.\"" }
entries[168616] = { ["name"] = "Stalwart Worldvein", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Worldvein Resonance.\nMajor Power:\nWorldvein Resonance\nInstant 1 min cooldown Concentrate energy into the Heart of Azeroth, immediately causing 3 Lifeblood Shards to erupt from the nearby ground for 18 sec, and incease the primary stat gained from Lifeblood Shards by 300% for 18 sec.\n\nLifeblood Shard\nGrants you and any other ally using Worldvein Resonance 13 primary stat while within 8 yds of the Lifeblood Shard. You can benefit from a maximum of 4 Lifeblood Shards at a time.\nMinor Power:\nLifeblood\nEvery 18-25 sec, a Lifeblood Shard erupts from the nearby ground for 18 sec.\n\nLifeblood Shard\nGrants you and any other ally using Worldvein Resonance 13 primary stat while within 8 yds of the Lifeblood Shard. You can benefit from a maximum of 4 Lifeblood Shards at a time.\n\"This Worldvein is solidly built and it appears to be bolstering the azerite around it.\"" }
entries[168617] = { ["name"] = "Fluctuating Worldvein", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Worldvein Resonance.\nLearn Rank 3 Worldvein Resonance on another character to unlock this essence.\nMajor Power:\nWorldvein Resonance\nInstant 1 min cooldown Concentrate energy into the Heart of Azeroth, immediately causing 3 Lifeblood Shards to erupt from the nearby ground for 18 sec, and incease the primary stat gained from Lifeblood Shards by 300% for 18 sec.\n\nLifeblood Shard\nGrants you and any other ally using Worldvein Resonance 13 primary stat while within 12 yds of the Lifeblood Shard. You can benefit from a maximum of 4 Lifeblood Shards at a time.\nMinor Power:\nLifeblood\nEvery 1-25 sec, a Lifeblood Shard erupts from the nearby ground for 18 sec.\n\nLifeblood Shard\nGrants you and any other ally using Worldvein Resonance 13 primary stat while within 12 yds of the Lifeblood Shard. You can benefit from a maximum of 4 Lifeblood Shards at a time.\n\"This Worldvein has a much faster internal vibration, it will likely attract Azerite Shards much more frequently.\"" }
entries[168618] = { ["name"] = "Brilliant Worldvein", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Worldvein Resonance.\nMajor Power:\nWorldvein Resonance\nInstant 1 min cooldown Concentrate energy into the Heart of Azeroth, immediately causing 3 Lifeblood Shards to erupt from the nearby ground for 18 sec, and incease the primary stat gained from Lifeblood Shards by 300% for 18 sec.\n\nLifeblood Shard\nGrants you and any other ally using Worldvein Resonance 13 primary stat while within 12 yds of the Lifeblood Shard. You can benefit from a maximum of 4 Lifeblood Shards at a time.\nMinor Power:\nLifeblood\nEvery 1-25 sec, a Lifeblood Shard erupts from the nearby ground for 18 sec.\n\nLifeblood Shard\nGrants you and any other ally using Worldvein Resonance 13 primary stat while within 12 yds of the Lifeblood Shard. You can benefit from a maximum of 4 Lifeblood Shards at a time.\n\"The brilliance and intensity of this Worldvein is awe inspiring.\"" }
