entries[168620] = { ["name"] = "Converging Lens of the Focusing Iris", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Essence of the Focusing Iris.\nMajor Power:\nFocused Azerite Beam\n2 sec cast 1.5 min cooldown Focus excess Azerite energy into the Heart of Azeroth, then expel that energy outward, dealing ( 757 * 10) Fire damage to all enemies in front of you over 3 sec.\nMinor Power:\nFocused Energy\nYour damaging spells and abilities grant you 5 Haste for 4 sec, stacking up to 10 times. This Haste is lost if you stop using spells or abilities against the initial target. (500ms cooldown)\n\"Azerite crystals forming on this ancient lens enhance its innate ability to bend and direct magic into a fiery torrent.\"" }
entries[168621] = { ["name"] = "Magnifying Lens of the Focusing Iris", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Essence of the Focusing Iris.\nMajor Power:\nFocused Azerite Beam\n1.333 sec cast 1.5 min cooldown Focus excess Azerite energy into the Heart of Azeroth, then expel that energy outward, dealing ( 891 * 10) Fire damage to all enemies in front of you over 3 sec.\nMinor Power:\nFocused Energy\nYour damaging spells and abilities grant you [source value] Haste for 4 sec, stacking up to 10 times. This Haste is lost if you stop using spells or abilities against the initial target.\n\"Azerite crystals forming on this ancient lens enhance its innate ability to bend and direct magic into a fiery torrent.\"", ["unresolvedValues"] = true }
entries[168622] = { ["name"] = "Stabilizing Lens of the Focusing Iris", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Essence of the Focusing Iris.\nLearn Rank 3 Focusing Iris, Life-Binder's Invocation, or Anima of Life and Death on another character to unlock this essence.\nMajor Power:\nFocused Azerite Beam\n1.333 sec cast 1.5 min cooldown Focus excess Azerite energy into the Heart of Azeroth, then expel that energy outward, dealing ( 891 * 10) Fire damage to all enemies in front of you over 3 sec. Castable while moving.\nMinor Power:\nFocused Energy\nYour damaging spells and abilities grant you [source value] Haste for 4 sec, stacking up to 10 times. This Haste is lost if you stop using spells or abilities against the initial target.\n\nWhen you have no stacks of Focused Energy, generate 3 stacks from your first damaging spell or ability.\n\"Azerite crystals forming on this ancient lens enhance its innate ability to bend and direct magic into a fiery torrent.\"", ["unresolvedValues"] = true }
entries[168623] = { ["name"] = "Biconcavic Lens of the Focusing Iris", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Essence of the Focusing Iris.\nMajor Power:\nFocused Azerite Beam\n1.333 sec cast 1.5 min cooldown Focus excess Azerite energy into the Heart of Azeroth, then expel that energy outward, dealing ( 891 * 10) Fire damage to all enemies in front of you over 3 sec. Castable while moving.\nMinor Power:\nFocused Energy\nYour damaging spells and abilities grant you [source value] Haste for 4 sec, stacking up to 10 times. This Haste is lost if you stop using spells or abilities against the initial target.\n\nWhen you have no stacks of Focused Energy, generate 3 stacks from your first damaging spell or ability.\n\"Azerite crystals forming on this ancient lens enhance its innate ability to bend and direct magic into a fiery torrent.\"", ["unresolvedValues"] = true }
