entries[168656] = { ["name"] = "Greater Mystical Cauldron", ["text"] = "Binds to Warband\nUse: Creates a cauldron that raid members can use to gain the benefit of a flask appropriate to their class and talents. Cauldron has 30 uses and lasts for 10 min.\nSell Price:" }
