entries[168783] = { ["name"] = "Pattern: Reinforced Seaweave Breeches", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft Reinforced Seaweave Breeches.\nCraft Reinforced Seaweave Breeches.\nRequires Kul Tiran Tailoring (170)\nSell Price:\nAlliance\nReinforced Seaweave Breeches\nBinds when picked up\nLegs Cloth\n6 Armor\n+7 Intellect\n+11 Stamina\n\nPrismatic Socket\n\nDurability 120 / 120\nSell Price:\nHorde\nReinforced Seaweave Breeches\nBinds when picked up\nLegs Cloth\n6 Armor\n+7 Intellect\n+11 Stamina\n\nPrismatic Socket\n\nDurability 120 / 120\nSell Price:\nRequires Gilded Seaweave (100), Embroidered Deep Sea Satin (25), Nylon Thread (55), Expulsom (35)" }
entries[168784] = { ["name"] = "Pattern: Banded Seaweave Breeches", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft Banded Seaweave Breeches.\nCraft Banded Seaweave Breeches.\nRequires Kul Tiran Tailoring (170)\nSell Price:\nAlliance\nBanded Seaweave Breeches\nBinds when picked up\nLegs Cloth\n6 Armor\n+8 Intellect\n+12 Stamina\n\nPrismatic Socket\n\nDurability 120 / 120\nSell Price:\nHorde\nBanded Seaweave Breeches\nBinds when picked up\nLegs Cloth\n6 Armor\n+8 Intellect\n+12 Stamina\n\nPrismatic Socket\n\nDurability 120 / 120\nSell Price:\nRequires Gilded Seaweave (115), Embroidered Deep Sea Satin (30), Nylon Thread (60), Expulsom (40)" }
entries[168785] = { ["name"] = "Subroutine: Defragmentation", ["text"] = "Red Punchcard\nBinds when picked up\nEquip: Heal for 7 every 1 sec , increased by up to 200% based on missing health.\nSell Price:" }
entries[168786] = { ["name"] = "Rotten Food", ["text"] = "\"The bugs eating it appear unusually intelligent.\"\nSell Price:" }
entries[168787] = { ["name"] = "Empty Birdcage", ["text"] = "\"There doesn't appear to be a way to place a bird inside of it.\"\nSell Price:" }
entries[168788] = { ["name"] = "Toy Soldier Weapons", ["text"] = "\"A handful of tiny weapons. Adorable, but utterly useless in combat.\"\nSell Price:" }
entries[168789] = { ["name"] = "Perpetual Motion Device", ["text"] = "\"It just keeps going faster and faster.\"\nSell Price:" }
entries[168790] = { ["name"] = "Sack of Fish Bones", ["text"] = "\"Seems fishy.\"\nSell Price:" }
entries[168791] = { ["name"] = "Shiny Rocks", ["text"] = "\"Maybe they're worth something?\"\nSell Price:" }
entries[168792] = { ["name"] = "Kobold's Candle", ["text"] = "\"Most likely taken without permission.\"\nSell Price:" }
entries[168793] = { ["name"] = "Bottle of Homemade Wine", ["text"] = "\"Contains a trace of vanilla, nutmeg, and oak leaves. It's probably wise to not drink it.\"\nSell Price:" }
entries[168794] = { ["name"] = "Last Year's Brewfest Flyer", ["text"] = "\"At least it's something.\"\nSell Price:" }
entries[168795] = { ["name"] = "Old Boot", ["text"] = "\"Smells of alcohol.\"\nSell Price:" }
entries[168796] = { ["name"] = "Recycled Scroll", ["text"] = "\"The enchantments on the paper were painted over, rendering it useless.\"\nSell Price:" }
entries[168797] = { ["name"] = "Stack of Undeliverable Mail", ["text"] = "\"The address is unreadable. Good news for you!\"\nSell Price:" }
entries[168798] = { ["name"] = "Trajectory Analysis", ["text"] = "Red Punchcard\nBinds when picked up\nEquip: Taking Physical damage grants 2 dodge for 6 sec. This effect stacks.\nSell Price:" }
entries[168799] = { ["name"] = "Steel Greatsword", ["text"] = "Binds when equipped\nTwo-Hand Sword\n1 - 3 Damage Speed 3.20\n(0.6 damage per second)\nSell Price:" }
entries[168800] = { ["name"] = "Subroutine: Recalibration", ["text"] = "Red Punchcard\nBinds when picked up\nEquip: Every 12 spells , gain 41 Haste for 12 sec, then lose 8 Haste for 6 sec.\nSell Price:" }
entries[168802] = { ["name"] = "Nazjatar Battle Commendation", ["text"] = "Binds when picked up\n\"Exchanged for rewards for participating in the Battle for Nazjatar.\"\nSell Price:" }
entries[168803] = { ["name"] = "Emergency Supplies", ["text"] = "Quest Item\n\"This crate contains various supplies incase of emergency. Food, water, bandages, and dwarven ale incase things get really dicey.\"" }
entries[168804] = { ["name"] = "Powered Piscine Procurement Pole", ["text"] = "Binds when picked up\nUnique\nFishing Tool Durability 65 / 65\nEquip: +15 Fishing Skill.\nRequires Fishing (1)\nSell Price:" }
entries[168806] = { ["name"] = "Mechanocat and Rider", ["text"] = "\"Special Issue: Customize your ride.\"\n<Right Click to Read>\nSell Price:" }
entries[168807] = { ["name"] = "Wormhole Generator: Kul Tiras", ["text"] = "Binds when used\nToy\nUse: Teleports the player to a random location on Kul Tiras. (15 Min Cooldown)\nRequires Kul Tiran Engineering (1)\n\"The user is responsible for final destinations teleported to, and may not take any legal action against the maker of this device.\"\nSell Price:" }
entries[168808] = { ["name"] = "Wormhole Generator: Zandalar", ["text"] = "Binds when used\nToy\nUse: Teleports the player to a random location on Zandalar. (15 Min Cooldown)\nRequires Kul Tiran Engineering (1)\n\"The user is responsible for final destinations teleported to, and may not take any legal action against the maker of this device.\"\nSell Price:" }
entries[168809] = { ["name"] = "Living Droplet", ["text"] = "Quest Item\n\"There is energy swirling within each drop.\"" }
entries[168810] = { ["name"] = "Iridescent Pearl", ["text"] = "Quest Item\n\"Perfection in pearl form.\"" }
entries[168811] = { ["name"] = "Wand of Absorption", ["text"] = "Quest Item\nUnique\nUse: Absorb the lingering essence of a targeted ogre. Will not work on the living." }
entries[168812] = { ["name"] = "Air Freshner", ["text"] = "\"Daffodil gold scented.\"\nSell Price:" }
entries[168813] = { ["name"] = "Robotic-Memory Recorder", ["text"] = "Quest Item\nUse: Scans the databanks of newly deceased Clockwork Giants within 10 yards. (4 Sec Cooldown)\n\"Scans the memory banks of robotic creatures\"" }
entries[168814] = { ["name"] = "Animated Blood of the Decimated", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Blood of the Enemy.\nMajor Power:\nBlood of the Enemy\nInstant 1.5 min cooldown The Heart of Azeroth erupts violently, dealing 1739 Shadow damage to enemies within 12 yds. You gain 25% critical strike chance against the targets for 10 sec, and increases your critical hit damage by 25% for 5 sec.\nMinor Power:\nBlood-Soaked\nYour critical strikes with spells and abilities grant a stack of Blood-Soaked, increasing Critical Strike by 2 . Upon reaching 40 stacks, you gain 125 Haste for 8 sec.\n\nBlood-Soaked has a 25% chance of only consuming 30 stacks." }
entries[168815] = { ["name"] = "Kelpberry Cask", ["text"] = "Quest Item\nUnique" }
entries[168816] = { ["name"] = "Pulsing Star Heart", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Spirit of Preservation.\nMajor Power:\nSpirit of Preservation\n40 yd range Channeled (3 sec cast) 1 min cooldown Channel a beam of energy onto an ally, healing them for [( 1452 * (5) + 1452 ) * (1 + Versatility)] over 3 sec. Up to 6 other allies in the beam are healed for [ 145 * (1 + Versatility)] every 0.6 sec.\n\nEach time Spirit of Preservation heals the primary target, gain a stack of Devout Spirit.\nMinor Power:\nDevout Spirit\nEvery 5 sec, gain Devout Spirit, causing your next Quick Heal to heal for an additional 153 , stacking up to 5 times.\n\nEach stack of Devout Spirit consumed increases the critical strike chance of your next Quick Heal within 15 sec by 20%.\n\nUnique: Corruption Resistance increased by 10." }
entries[168817] = { ["name"] = "Siphoning Crystal", ["text"] = "Quest Item\nUnique\nUse: Drain the magic from a nearby Ley Line Accumulator." }
entries[168818] = { ["name"] = "Sivara's Slitherblade", ["text"] = "Binds when picked up\nOne-Hand Dagger\n5 - 9 Damage Speed 1.80\n(3.9 damage per second)\n+3 Agility\n+5 Stamina\n+ 2 Critical Strike\n+ 4 Haste\nDurability 80 / 80\nSell Price:" }
entries[168821] = { ["name"] = "Emergency Rocket Chicken", ["text"] = "Binds when picked up\nUse: Useful for avoiding stabilizer damage from sudden gravity inflicted impacts. Hold on tight! (3 Min Cooldown)" }
entries[168822] = { ["name"] = "Thin Jelly", ["text"] = "Requires any Alliance race\n\"Runny and pale. Mildly satisfying for growing bees.\"\nSell Price:" }
entries[168823] = { ["name"] = "Rusty Mechanocrawler", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The check engine light is always on, it's when it goes off that you should be worried.\"\nDrop:\nMechagon" }
entries[168824] = { ["name"] = "Ocean Simulator", ["text"] = "Binds when picked up\nToy\nUse: Immerse yourself in the sounds of the ocean. (1 Min Cooldown)\n\"No matter where you are, find a moment of peace. Enjoy the soothing sounds of the seashore.\"" }
entries[168825] = { ["name"] = "Rich Jelly", ["text"] = "Requires any Alliance race\n\"Thick and golden. Satisfying for growing bees.\"\nSell Price:" }
entries[168826] = { ["name"] = "Mechagon Peacekeeper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Keeps the peace by turning you into pieces.\"\nDrop:\nHK-8 Aerial Oppression Unit\nZone:\nOperation: Mechagon (Mythic)" }
entries[168827] = { ["name"] = "Scrapforged Mechaspider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"You built this yourself, you should be proud, even though it's smoky, sparky, and loud.\"\nQuest:\nDrive It Away Today\nZone:\nMechagon" }
entries[168828] = { ["name"] = "Royal Jelly", ["text"] = "Requires any Alliance race\n\"Fit for a queen. Highly satisfying for growing bees.\"\nSell Price:" }
entries[168829] = { ["name"] = "Rustbolt Resistor", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Rustbolt Resistance\n- Exalted\n\n\"R E S I S T\" is carved into the seat in crude letters, along with several, more profane things.\nVendor:\nStolen Royal Vendorbot\nZone:\nMechagon\nFaction:\nRustbolt Resistance - Exalted\nCost:" }
entries[168830] = { ["name"] = "Aerial Unit R-21/X", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"King Mechagon's private aerial unit, complete with deployable blast cannon and foot warmers.\"\nDrop:\nKing Mechagon" }
entries[168832] = { ["name"] = "Galvanic Oscillator", ["text"] = "Mechagon Tinkering\nBinds when picked up\nCrafting Reagent\n\"A critical component in the most advanced augmentations.\"\nSell Price:" }
entries[168833] = { ["name"] = "Experimental Adventurer Augmentation", ["text"] = "Binds when picked up\nUnique\n\"Creates a powerful Ring or Trinket for your Specialization.\"\n<Right Click to Open>" }
entries[168834] = { ["name"] = "De-Synced Vibro Blade", ["text"] = "Binds when picked up\nThis Item Begins a Quest\nRequires any Horde race" }
entries[168835] = { ["name"] = "De-Synced Vibro Blade", ["text"] = "Binds when picked up\nThis Item Begins a Quest\nRequires any Alliance race" }
entries[168837] = { ["name"] = "Depth Forged Aegis", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Aegis of the Deep.\nRequires Friendly reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Friendly reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nAegis of the Deep\nInstant 1.5 min cooldown The elements protect you, reducing the damage you take from each attack by 395 for 15 sec .\nMinor Power:\nStand Your Ground\nYou gain 13 Versatility for each enemy within 10 yards, up to ( 13 * 10) Versatility." }
entries[168838] = { ["name"] = "Enduring Bulwark of the Depths", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Aegis of the Deep.\nRequires Honored reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Honored reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nAegis of the Deep\nInstant 1.133 min cooldown The elements protect you, reducing the damage you take from each attack by 395 for 15 sec.\nMinor Power:\nStand Your Ground\nYou gain 13 Versatility for each enemy within 10 yards, up to ( 13 * 10) Versatility. While below 35% health the Versatility amount is doubled." }
entries[168839] = { ["name"] = "Regenerating Barrier of the Depths", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Aegis of the Deep.\nLearn any Rank 3 Nazjatar reputation essence on another character to unlock this essence.\nRequires Revered reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Revered reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nAegis of the Deep\nInstant 1.133 min cooldown The elements protect you, reducing the damage you take from each attack by 395 for 15 sec, and when Aegis of the Deep fades gain 27 Avoidance for 6 sec.\nMinor Power:\nStand Your Ground\nYou gain 13 Versatility for each enemy within 10 yards, up to ( 13 * 10) Versatility. While below 35% health the Versatility amount is doubled.\n\nHeal for 208 health every 4 sec for each stack of Stand Your Ground on you." }
entries[168840] = { ["name"] = "Resplendent Bastion of the Depths", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Aegis of the Deep.\nMajor Power:\nAegis of the Deep\nInstant 1.133 min cooldown The elements protect you, reducing the damage you take from each attack by 395 for 15 sec, and when Aegis of the Deep fades gain 27 Avoidance for 6 sec.\nMinor Power:\nStand Your Ground\nYou gain 13 Versatility for each enemy within 10 yards, up to ( 13 * 10) Versatility. While below 35% health the Versatility amount is doubled.\n\nHeal for 208 health every 4 sec for each stack of Stand Your Ground on you." }
entries[168841] = { ["name"] = "Scroll of Shirakess", ["text"] = "Quest Item\nUnique (8)\n\"Dark incantations writhe across the scroll.\"" }
entries[168842] = { ["name"] = "Engine of Mecha-Perfection", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Vision of Perfection.\nMajor Power:\nVision of Perfection\nYour spells and abilities have a chance to activate for 25% of its base duration .\nMinor Power:\nStrive for Perfection\nReduces the cooldown of by [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% .\n\"Building upon an ancient titan device, the engine is a triumph of gnomish ingenuity that allows mechanized beings to achieve peak performance.\"" }
entries[168843] = { ["name"] = "Perfectly Timed Differential", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Vision of Perfection.\nMajor Power:\nVision of Perfection\nYour spells and abilities have a chance to activate for 35% of its base duration .\nMinor Power:\nStrive for Perfection\nReduces the cooldown of by [(( 6849 + 3320) /- 100) ; Min 10, Max 25]%.\n\nWhen you activate , immediately heal for 5% of maximum health." }
entries[168844] = { ["name"] = "Perfection-Enhancing Gearbox", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Vision of Perfection.\nLearn Rank 3 Vision of Perfection on another character to unlock this essence.\nMajor Power:\nVision of Perfection\nYour spells and abilities have a chance to activate for 35% of its base duration .\n\nWhen the Vision of Perfection activates, you and up to 2 other nearby allies gain 24 Haste for 10 sec.\nMinor Power:\nStrive for Perfection\nReduces the cooldown of by [(( 6849 + 3320) /- 100) ; Min 10, Max 25]%, and increases your Versatility by 18 .\n\nWhen you activate , immediately heal for 5% of maximum health." }
entries[168845] = { ["name"] = "Mecha-Perfection Turbo", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Vision of Perfection.\nMajor Power:\nVision of Perfection\nYour spells and abilities have a chance to activate for 35% of its base duration .\n\nWhen the Vision of Perfection activates, you and up to 2 other nearby allies gain 24 Haste for 10 sec.\nMinor Power:\nStrive for Perfection\nReduces the cooldown of by [(( 6849 + 3320) /- 100) ; Min 10, Max 25]%, and increases your Versatility by 18 .\n\nWhen you activate , immediately heal for 5% of maximum health.\n\"Improving upon the Engine of Mecha-Perfection, this turbo has the potential to unleash massive amounts of titan energy in a single instant.\"" }
entries[168846] = { ["name"] = "Pearl of Lucid Dreams", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Memory of Lucid Dreams.\nMajor Power:\nMemory of Lucid Dreams\nInstant 2 min cooldown Clear your mind and attune yourself with the Heart of Azeroth, increasing your generation rate by 100% for 12 sec.\nMinor Power:\nLucid Dreams\nYour spells and abilities have a chance to refund 50% of the spent on them and heal you for [ 764 * (1 + Versatility)] ." }
entries[168847] = { ["name"] = "Pearl of Manifest Ambitions", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Memory of Lucid Dreams.\nRequires the achievement \"Tour of the Depths\". (Cannot purchase if already known.)\nMajor Power:\nMemory of Lucid Dreams\nInstant 2 min cooldown Clear your mind and attune yourself with the Heart of Azeroth, increasing your generation rate by 100% for 15 sec.\nMinor Power:\nLucid Dreams\nYour spells and abilities have a chance to refund 50% of the spent on them and heal you for [ 764 * 1.5 * (1 + Versatility)] ." }
entries[168848] = { ["name"] = "Pearl of Perspicuous Intentions", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Memory of Lucid Dreams.\nLearn Rank 3 Memory of Lucid Dreams on another character to unlock this essence.\nRequires the achievement \"Nautical Battlefield Training\". (Cannot purchase if already known.)\nMajor Power:\nMemory of Lucid Dreams\nInstant 2 min cooldown Clear your mind and attune yourself with the Heart of Azeroth, increasing your generation rate by 100% and your Leech by 66 for 15 sec.\nMinor Power:\nLucid Dreams\nYour spells and abilities have a chance to refund 50% of the spent on them , heal you for [ 764 * (1.5) * (1 + Versatility)], and increase your Versatility by 74 for 8 sec." }
entries[168849] = { ["name"] = "Pearl of Luminous Designs", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Memory of Lucid Dreams.\nMajor Power:\nMemory of Lucid Dreams\nInstant 2 min cooldown Clear your mind and attune yourself with the Heart of Azeroth, increasing your generation rate by 100% and your Leech by 66 for 15 sec.\nMinor Power:\nLucid Dreams\nYour spells and abilities have a chance to refund 50% of the spent on them , heal you for [ 764 * (1.5) * (1 + Versatility)], and increase your Versatility by 74 for 8 sec." }
entries[168850] = { ["name"] = "Time-Lost Battlefield Memento", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Ripple in Space.\nMajor Power:\nRipple in Space\n25 yd range Instant 1 min cooldown Create an Azerite beacon at a target location. After 4 sec, the Heart of Azeroth will relocate you to this beacon and deal 1451 Fire damage to all nearby enemies.\nMinor Power:\nReality Shift\nWhen you move more than 25 yds within 4 sec, gain 47 primary stat for 15 sec.\n\nThis can only occur once every 30 sec.\n\"The memories of the past hold a deep power that draws us back to moments of great importance.\"" }
entries[168851] = { ["name"] = "Enduring Battlefield Memento", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Ripple in Space.\nRequires the achievement \"Fighting on Two Fronts\". (Cannot purchase if already known.)\nMajor Power:\nRipple in Space\n25 yd range Instant 1 min cooldown Create an Azerite beacon at a target location. After 2 sec, the Heart of Azeroth will relocate you to this beacon and deal 1451 Fire damage to all nearby enemies.\nMinor Power:\nReality Shift\nWhen you move more than 25 yds within 4 sec, gain 47 primary stat for 20 sec.\n\nThis can only occur once every 30 sec." }
entries[168852] = { ["name"] = "Stalwart Battlefield Memento", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Ripple in Space.\nLearn Rank 3 Ripple in Space on another character to unlock this essence.\nYou do not have enough Call to Arms Distinctions to purchase this item.\nMajor Power:\nRipple in Space\n25 yd range Instant 1 min cooldown Create an Azerite beacon at a target location. After 2 sec, the Heart of Azeroth will relocate you to this beacon and deal 1451 Fire damage to all nearby enemies.\n\nFor 10 sec after being relocated, you take 10% reduced damage.\nMinor Power:\nReality Shift\nYour movement speed is increased by 5%, and when you move more than 25 yds within 4 sec, gain 47 primary stat for 20 sec.\n\nThis can only occur once every 30 sec." }
entries[168853] = { ["name"] = "Glinting Battlefield Memento", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Ripple in Space.\nMajor Power:\nRipple in Space\n25 yd range Instant 1 min cooldown Create an Azerite beacon at a target location. After 2 sec, the Heart of Azeroth will relocate you to this beacon and deal 1451 Fire damage to all nearby enemies.\n\nFor 10 sec after being relocated, you take 10% reduced damage.\nMinor Power:\nReality Shift\nYour movement speed is increased by 5%, and when you move more than 25 yds within 4 sec, gain 47 primary stat for 20 sec.\n\nThis can only occur once every 30 sec." }
entries[168854] = { ["name"] = "Animated Elemental Heart", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Condensed Life-Force.\nMajor Power:\nGuardian of Azeroth\nInstant 3 min cooldown Call upon Azeroth to summon a Guardian of Azeroth for 30 sec who impales your target with spikes of Azerite every 2.5 sec that deal [ 660 * (1 + Versatility)] Fire damage.\nMinor Power:\nCondensed Life-Force\nApproximately 2 procs per minute Your spells and abilities have a high chance to impale your target with a spike of Azerite, causing [ 660 * (1 + Versatility)] Fire damage.\n\"Even the most awe-inspiring elemental lords are born from simple hearts of stone.\"" }
entries[168855] = { ["name"] = "Pulsing Elemental Heart", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Condensed Life-Force.\nMajor Power:\nGuardian of Azeroth\nInstant 3 min cooldown Call upon Azeroth to summon a Guardian of Azeroth for 30 sec who impales your target with spikes of Azerite every 2.5 sec that deal [ 660 * (1 + Versatility) * (1.25)] Fire damage. Every 8 sec, the Guardian launches a volley of Azerite Spikes at its target, dealing 670 Fire damage to all nearby enemies.\nMinor Power:\nCondensed Life-Force\nApproximately 2 procs per minute Your spells and abilities have a high chance to impale your target with a spike of Azerite, causing [ 660 * (1 + Versatility) * (1.25)] Fire damage.\n\"Even the most awe-inspiring elemental lords are born from simple hearts of stone.\"" }
entries[168856] = { ["name"] = "Resonating Elemental Heart", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Condensed Life-Force.\nLearn Rank 3 Condensed Life-Force, Vitality Conduit, or Azeroth's Undying Gift on another character to unlock this essence.\nMajor Power:\nGuardian of Azeroth\nInstant 3 min cooldown Call upon Azeroth to summon a Guardian of Azeroth for 30 sec who impales your target with spikes of Azerite every 2.5 sec that deal [ 660 * (1 + Versatility) * (1.25)] Fire damage. Every 8 sec, the Guardian launches a volley of Azerite Spikes at its target, dealing 670 Fire damage to all nearby enemies.\n\nEach time the Guardian of Azeroth casts a spell, you gain 2% Haste, stacking up to 5 times. This effect ends when the Guardian of Azeroth despawns.\nMinor Power:\nCondensed Life-Force\nApproximately 2 procs per minute Your spells and abilities have a high chance to impale your target with a spike of Azerite, causing [ 660 * (1 + Versatility) * (1.25)] Fire damage.\n\nWhen an Azerite spike deals damage, all damage you deal against that target is increased by 3% for 6 sec.\n\"Even the most awe-inspiring elemental lords are born from simple hearts of stone.\"" }
entries[168857] = { ["name"] = "Sparkling Elemental Heart", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Condensed Life-Force.\nMajor Power:\nGuardian of Azeroth\nInstant 3 min cooldown Call upon Azeroth to summon a Guardian of Azeroth for 30 sec who impales your target with spikes of Azerite every 2.5 sec that deal [ 660 * (1 + Versatility) * (1.25)] Fire damage. Every 8 sec, the Guardian launches a volley of Azerite Spikes at its target, dealing 670 Fire damage to all nearby enemies.\n\nEach time the Guardian of Azeroth casts a spell, you gain 2% Haste, stacking up to 5 times. This effect ends when the Guardian of Azeroth despawns.\nMinor Power:\nCondensed Life-Force\nApproximately 2 procs per minute Your spells and abilities have a high chance to impale your target with a spike of Azerite, causing [ 660 * (1 + Versatility) * (1.25)] Fire damage.\n\nWhen an Azerite spike deals damage, all damage you deal against that target is increased by 3% for 6 sec.\n\"Even the most awe-inspiring elemental lords are born from simple hearts of stone.\"" }
entries[168858] = { ["name"] = "Titan Purification Protocols", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Purification Protocol.\nRequires Friendly reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nMajor Power:\nPurifying Blast\n40 yd range Instant 1 min cooldown Call down a purifying beam upon the target area, dealing [ 395 * (1 + Versatility) * 7] Fire damage over 6 sec.\n\nAny Aberration struck by the beam is stunned for 3 sec.\nMinor Power:\nPurification Protocol\nApproximately 2 procs per minute MOTHER has added a Purification Protocol to your Heart of Azeroth, allowing your damaging spells and abilities to release a blast of Azerite energy at your target, dealing [ 563 * (1 + Versatility)] Fire damage to any enemy within 8 yds .\n\nPurification Protocol deals 50% additional damage against Aberrations.\n\"The titans set down protocols to deal with the various corruptions that Azeroth might face.\"" }
entries[168859] = { ["name"] = "Targeted Purification Protocols", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Purification Protocol.\nRequires Honored reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nMajor Power:\nPurifying Blast\n40 yd range Instant 1 min cooldown Call down a purifying beam upon the target area, dealing [ 395 * (1 + Versatility) * 7] Fire damage over 6 sec. Has a low chance to immediately annihilate any specimen deemed unworthy by MOTHER.\n\nAny Aberration struck by the beam is stunned for 3 sec.\nMinor Power:\nPurification Protocol\nApproximately 2 procs per minute MOTHER has added a Purification Protocol to your Heart of Azeroth, allowing your damaging spells and abilities to release a blast of Azerite energy at your target, dealing [ 563 * (1 + Versatility)] Fire damage to any enemy within 8 yds, and heals you for [ 255 * (1 + Versatility)] every 2 sec for 8 sec.\n\nPurification Protocol deals 50% additional damage against Aberrations.\n\"For instances of extreme precision.\"" }
entries[168860] = { ["name"] = "Enhanced Purification Protocols", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Purification Protocol.\nRequires Revered reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nLearn any Rank 3 Rustbolt Resistance essence on another character to unlock this essence.\nMajor Power:\nPurifying Blast\n40 yd range Instant 1 min cooldown Call down a purifying beam upon the target area, dealing [ 395 * (1 + Versatility) * 7] Fire damage over 6 sec. Has a low chance to immediately annihilate any specimen deemed unworthy by MOTHER.\n\nWhen an enemy dies within the beam, your damage is increased by 10% for 8 sec.\n\nAny Aberration struck by the beam is stunned for 3 sec.\nMinor Power:\nPurification Protocol\nApproximately 2 procs per minute MOTHER has added a Purification Protocol to your Heart of Azeroth, allowing your damaging spells and abilities to release a blast of Azerite energy at your target, dealing [ 563 * (1.25) * (1 + Versatility)] Fire damage to any enemy within 8 yds, and heals you for [ 255 * (1 + Versatility)] every 2 sec for 8 sec.\n\nPurification Protocol deals 50% additional damage against Aberrations.\n\"When previous protocols are not effective.\"" }
entries[168861] = { ["name"] = "Ultimate Purification Protocols", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Purification Protocol.\nMajor Power:\nPurifying Blast\n40 yd range Instant 1 min cooldown Call down a purifying beam upon the target area, dealing [ 395 * (1 + Versatility) * 7] Fire damage over 6 sec. Has a low chance to immediately annihilate any specimen deemed unworthy by MOTHER.\n\nWhen an enemy dies within the beam, your damage is increased by 10% for 8 sec.\n\nAny Aberration struck by the beam is stunned for 3 sec.\nMinor Power:\nPurification Protocol\nApproximately 2 procs per minute MOTHER has added a Purification Protocol to your Heart of Azeroth, allowing your damaging spells and abilities to release a blast of Azerite energy at your target, dealing [ 563 * (1.25) * (1 + Versatility)] Fire damage to any enemy within 8 yds, and heals you for [ 255 * (1 + Versatility)] every 2 sec for 8 sec.\n\nPurification Protocol deals 50% additional damage against Aberrations.\n\"When all else fails.\"" }
entries[168862] = { ["name"] = "G.E.A.R. Tracking Beacon", ["text"] = "Binds when picked up\nUnique\nRaces: Gnome\nUse: Request a pickup to the nearest flight master.\n\nOnly works in areas in which you have unlocked the use of the flight whistle.\nSell Price:" }
entries[168863] = { ["name"] = "Unbound Azerite Slivershards", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Unbound Force.\nRequires Friendly reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Friendly reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nThe Unbound Force\n40 yd range Instant 1 min cooldown Unleash the forces within the Heart of Azeroth, causing shards of Azerite to strike your target for [source value] Fire damage over 2 sec. This damage is increased by 300% if it critically strikes.\nMinor Power:\nReckless Force\nApproximately 20 procs per minute When an ability fails to critically strike, you have a high chance to gain Reckless Force. When Reckless Force reaches 20 stacks, your critical strike is increased by 50% for 4 sec.", ["unresolvedValues"] = true }
entries[168864] = { ["name"] = "Sharpened Azerite Slivershards", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Unbound Force.\nRequires Honored reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Honored reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nThe Unbound Force\n40 yd range Instant 45 sec cooldown Unleash the forces within the Heart of Azeroth, causing shards of Azerite to strike your target for [source value] Fire damage over 2 sec. This damage is increased by 300% if it critically strikes.\nMinor Power:\nReckless Force\nWhen an ability fails to critically strike, you have a high chance to gain Reckless Force. When Reckless Force reaches 20 stacks, your critical strike is increased by 70% for 4 sec.", ["unresolvedValues"] = true }
entries[168865] = { ["name"] = "Polarized Azerite Slivershards", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Unbound Force.\nLearn any Rank 3 Nazjatar reputation essence on another character to unlock this essence.\nRequires Revered reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Revered reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nThe Unbound Force\n40 yd range Instant 45 sec cooldown Unleash the forces within the Heart of Azeroth, causing shards of Azerite to strike your target for [source value] Fire damage over 2 sec. This damage is increased by 300% if it critically strikes.\n\nEach time The Unbound Force causes a critical strike, it immediately strikes the target with an additional Azerite shard, up to a maximum of 5.\nMinor Power:\nReckless Force\nWhen an ability fails to critically strike, you have a high chance to gain Reckless Force. When Reckless Force reaches 20 stacks, your critical strike is increased by 70% for 6 sec.", ["unresolvedValues"] = true }
entries[168866] = { ["name"] = "Incandescent Azerite Slivershards", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Unbound Force.\nMajor Power:\nThe Unbound Force\n40 yd range Instant 45 sec cooldown Unleash the forces within the Heart of Azeroth, causing shards of Azerite to strike your target for [source value] Fire damage over 2 sec. This damage is increased by 300% if it critically strikes.\n\nEach time The Unbound Force causes a critical strike, it immediately strikes the target with an additional Azerite shard, up to a maximum of 5.\nMinor Power:\nReckless Force\nWhen an ability fails to critically strike, you have a high chance to gain Reckless Force. When Reckless Force reaches 20 stacks, your critical strike is increased by 70% for 6 sec.", ["unresolvedValues"] = true }
