entries[168920] = { ["name"] = "Azerite-Encrusted Timequartz", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Artifice of Time.\nMajor Power:\nStandstill\n40 yd range Instant 3 min cooldown Create a time vortex around a friendly target, absorbing 34942 damage and 34942 healing for 4 sec. When this expires, the absorbed damage and healing is delivered over 10 sec .\nMinor Power:\nArtifice of Time\nApproximately 10 procs per minute Your heals have a very high chance to grant the target 72 Haste for 6 sec.\n\"There is always time for a pause in battle.\"" }
entries[168921] = { ["name"] = "Azerite-Infused Timequartz", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Artifice of Time.\nRequires the achievement \"Battlefield Brawler\". (Cannot purchase if already known.)\nMajor Power:\nStandstill\n40 yd range Instant 3 min cooldown Create a time vortex around a friendly target, absorbing 34942 damage and 34942 healing for 6 sec. When this expires, the absorbed damage and healing is delivered over 10 sec .\nMinor Power:\nArtifice of Time\nApproximately 10 procs per minute Your heals have a very high chance to grant the target 86 Haste for 8 sec.\n\"There is always time for a pause in battle.\"" }
entries[168922] = { ["name"] = "Azerite-Fueled Timequartz", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Artifice of Time.\nRequires the achievement \"Battlefield Tactician\". (Cannot purchase if already known.)\nLearn Rank 3 Blood of the Enemy, Artifice of Time, or Sphere of Suppression on another character to unlock this essence.\nMajor Power:\nStandstill\n40 yd range Instant 3 min cooldown Create a time vortex around a friendly target, absorbing 34942 damage and 34942 healing for 6 sec. When this expires, the absorbed damage and healing is delivered over 10 sec, and the damage is reduced by 20%.\nMinor Power:\nArtifice of Time\nApproximately 10 procs per minute Your heals have a very high chance to grant the target 86 Haste and 72 Speed for 8 sec.\n\"There is always time for a pause in battle.\"" }
entries[168923] = { ["name"] = "Unburdened Azerite Timequartz", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Artifice of Time.\nMajor Power:\nStandstill\n40 yd range Instant 3 min cooldown Create a time vortex around a friendly target, absorbing 34942 damage and 34942 healing for 6 sec. When this expires, the absorbed damage and healing is delivered over 10 sec, and the damage is reduced by 20%.\nMinor Power:\nArtifice of Time\nApproximately 10 procs per minute Your heals have a very high chance to grant the target 86 Haste and 72 Speed for 8 sec.\n\"There is always time for a pause in battle.\"" }
entries[168924] = { ["name"] = "Bursting Seed of Life", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Life-Binder's Invocation.\nMajor Power:\nLife-Binder's Invocation\n2.5 sec cast 2.5 min cooldown Implant 30 Seeds of Eonar divided over all allies within 30 yds.\n\nSeed of Eonar\nIf the target takes damage, the Seed bursts, healing them for 436 .\nMinor Power:\nSeed of Eonar\nApproximately 15 procs per minute Your heals have a very high chance to implant a Seed of Eonar in the target for 12 sec.\n\nSeed of Eonar\nIf the target takes damage, the Seed bursts, healing them for 436 .\n\"Eonar showered Azeroth with the first seeds of life, yet only a few still retain the titan's power within them.\"" }
entries[168925] = { ["name"] = "Replicating Seed of Abundance", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Life-Binder's Invocation.\nMajor Power:\nLife-Binder's Invocation\n2.5 sec cast 2.5 min cooldown Implant 40 Seeds of Eonar divided over all allies within 30 yds.\n\nSeed of Eonar\nIf the target takes damage, the Seed bursts, healing them for 436 .\nMinor Power:\nSeed of Eonar\nApproximately 15 procs per minute Your heals have a very high chance to implant a Seed of Eonar in the target for 15 sec.\n\nSeed of Eonar\nIf the target takes damage, the Seed bursts, healing them for 436 .\n\"Eonar showered Azeroth with the first seeds of life, yet only a few still retain the titan's power within them.\"" }
entries[168926] = { ["name"] = "Lingering Seed of Renewal", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Life-Binder's Invocation.\nLearn Rank 3 Focusing Iris, Life-Binder's Invocation, or Anima of Life and Death on another character to unlock this essence.\nMajor Power:\nLife-Binder's Invocation\n2.5 sec cast 2.5 min cooldown Implant 40 Seeds of Eonar divided over all allies within 30 yds.\n\nSeeds that expire unused reduce the cooldown of this ability by 2 sec.\n\nSeed of Eonar\nHeals for 21 every 1 sec. If the target takes damage, the Seed bursts, healing them for 436 .\nMinor Power:\nSeed of Eonar\nApproximately 15 procs per minute Your heals have a very high chance to implant a Seed of Eonar in the target for 15 sec.\n\nSeed of Eonar\nHeals for 21 every 1 sec. If the target takes damage, the Seed bursts, healing them for 436 .\n\"Eonar showered Azeroth with the first seeds of life, yet only a few still retain the titan's power within them.\"" }
entries[168927] = { ["name"] = "Seed of Vibrant Blooms", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Life-Binder's Invocation.\nMajor Power:\nLife-Binder's Invocation\n2.5 sec cast 2.5 min cooldown Implant 40 Seeds of Eonar divided over all allies within 30 yds.\n\nSeeds that expire unused reduce the cooldown of this ability by 2 sec.\n\nSeed of Eonar\nHeals for 21 every 1 sec. If the target takes damage, the Seed bursts, healing them for 436 .\nMinor Power:\nSeed of Eonar\nApproximately 15 procs per minute Your heals have a very high chance to implant a Seed of Eonar in the target for 15 sec.\n\nSeed of Eonar\nHeals for 21 every 1 sec. If the target takes damage, the Seed bursts, healing them for 436 .\n\"Eonar showered Azeroth with the first seeds of life, yet only a few still retain the titan's power within them.\"" }
entries[168928] = { ["name"] = "Tablet of the Balancing Tides", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Ever-Rising Tide.\nRequires Friendly reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Friendly reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nOvercharge Mana\nInstant 30 sec cooldown Overcharge your mana for 8 sec, causing each spell you cast to increase your healing by 3%, stacking.\n\nWhile overcharged, your mana regeneration is halted .\nMinor Power:\nThe Ever-Rising Tide\nApproximately 1.75 procs per minute Your heals have a chance to grant either 115 Intellect for 10 sec or 477 mana. Chance of receiving mana increases with your missing mana. (3.5s cooldown)\n\"The whispers of Elune and Neptulon play on the tides, their words etched in stone are a tribute to the balance of their powers.\"" }
entries[168929] = { ["name"] = "Codex of the Never-Ending Tides", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Ever-Rising Tide.\nRequires Honored reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Honored reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nOvercharge Mana\nInstant 30 sec cooldown Overcharge your mana for 8 sec, causing each spell you cast to increase your healing by 4%, stacking.\n\nWhile overcharged, your mana regeneration is halted .\nMinor Power:\nThe Ever-Rising Tide\nApproximately 1.75 procs per minute Your heals have a chance to grant either [source value] Intellect for 10 sec or [source value] mana. Chance of receiving mana increases with your missing mana. [The Ever-Rising Tide: 20% chance to gain both effects ] (3.5s cooldown)", ["unresolvedValues"] = true }
entries[168930] = { ["name"] = "Tome of the Quickening Tides", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Ever-Rising Tide.\nLearn any Rank 3 Nazjatar reputation essence on another character to unlock this essence.\nRequires Revered reputation with the Unshackled. (Cannot purchase if already known.)\nRequires Revered reputation with the Ankoan. (Cannot purchase if already known.)\nMajor Power:\nOvercharge Mana\nInstant 30 sec cooldown Overcharge your mana for 8 sec, causing each spell you cast to increase your healing by 4%, stacking.\n\nWhile overcharged, your mana regeneration is halted, and you gain 10% haste.\nMinor Power:\nThe Ever-Rising Tide\nApproximately 1.75 procs per minute Your heals have a chance to grant either [source value] Intellect for 10 sec or [source value] mana. Chance of receiving mana increases with your missing mana. 20% chance to gain both effects. (3.5s cooldown)", ["unresolvedValues"] = true }
entries[168931] = { ["name"] = "Vellum of Illuminating Tides", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Ever-Rising Tide.\nMajor Power:\nOvercharge Mana\nInstant 30 sec cooldown Overcharge your mana for 8 sec, causing each spell you cast to increase your healing by 4%, stacking.\n\nWhile overcharged, your mana regeneration is halted, and you gain 10% haste.\nMinor Power:\nThe Ever-Rising Tide\nApproximately 1.75 procs per minute Your heals have a chance to grant either [source value] Intellect for 10 sec or [source value] mana. Chance of receiving mana increases with your missing mana. 20% chance to gain both effects. (3.5s cooldown)", ["unresolvedValues"] = true }
entries[168932] = { ["name"] = "Reactive Existence Battery", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Well of Existence.\nRequires Friendly reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nMajor Power:\nRefreshment\n100 yd range Instant 15 sec cooldown Release all healing stored in The Well of Existence into an ally. This healing is amplified by 20 %.\nMinor Power:\nThe Well of Existence\n15% of your overhealing is stored in The Well of Existence. When you heal a target under 40% health, the Well releases up to 547 of its stored healing into them." }
entries[168933] = { ["name"] = "Enhanced Existence Capacitor", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Well of Existence.\nRequires Honored reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nMajor Power:\nRefreshment\n100 yd range Instant 15 sec cooldown Release all healing stored in The Well of Existence into an ally. This healing is amplified by 50%.\nMinor Power:\nThe Well of Existence\n15% of your overhealing is stored in The Well of Existence. When you heal a target under 50% health, the Well releases up to 547 of its stored healing into them." }
entries[168934] = { ["name"] = "Calibrated Existence Gauge", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Well of Existence.\nRequires Revered reputation with the Rustbolt Resistance. (Cannot purchase if already known.)\nLearn any Rank 3 Rustbolt Resistance essence on another character to unlock this essence.\nMajor Power:\nRefreshment\n100 yd range Instant 15 sec cooldown Release all healing stored in The Well of Existence into an ally. This healing is amplified by 50%. The Well will not release more healing than needed to fully heal the target.\nMinor Power:\nThe Well of Existence\n15% of your overhealing is stored in The Well of Existence. When you heal a target under 50% health, the Well releases up to 547 of its stored healing into them.\n\nWhen the Well contains less than 1398 healing, it absorbs healing twice as quickly." }
entries[168935] = { ["name"] = "Existence Vibrancy Display", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Well of Existence.\nMajor Power:\nRefreshment\n100 yd range Instant 15 sec cooldown Release all healing stored in The Well of Existence into an ally. This healing is amplified by 50%. The Well will not release more healing than needed to fully heal the target.\nMinor Power:\nThe Well of Existence\n15% of your overhealing is stored in The Well of Existence. When you heal a target under 50% health, the Well releases up to 547 of its stored healing into them.\n\nWhen the Well contains less than 1398 healing, it absorbs healing twice as quickly." }
entries[168936] = { ["name"] = "Ward of Unwavering Hope", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Unwavering Ward.\nMajor Power:\nGuardian Shell\nChanneled (4 sec cast) 3 min cooldown Release 12 protective spheres outward over 4 sec, granting the first ally to touch it a barrier that absorbs 1840 damage for 10 sec.\nMinor Power:\nUnwavering Ward\nEvery 10 sec, allies within 15 yds gain a shield that absorbs [ 113 * (1 + Versatility)] damage, stacking up to [ 848 * (1 + Versatility)].\n\nUnique: Corruption Resistance increased by 10." }
entries[168937] = { ["name"] = "Ward of Reciprocation", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Unwavering Ward.\nMajor Power:\nGuardian Shell\nChanneled (4 sec cast) 3 min cooldown Release 12 protective spheres outward over 4 sec, granting the first ally to touch it a barrier that absorbs 1840 damage for 10 sec.\n\nEach time you send out a protective sphere, gain an absorb shield for 2% of your maximum health.\nMinor Power:\nUnwavering Ward\nEvery 10 sec, allies within 15 yds gain a shield that absorbs [ 113 * (1 + Versatility)] damage, stacking up to [ 848 * (1 + Versatility) * (1.2)].\n\nUnique: Corruption Resistance increased by 10.\n\"Do unto others, as...\"" }
entries[168938] = { ["name"] = "Ward of Mutual Aid", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Unwavering Ward.\nLearn any Rank 3 essence from Horrific Visions on another character to unlock this essence.\nMajor Power:\nGuardian Shell\nChanneled (4 sec cast) 3 min cooldown Release 12 protective spheres outward over 4 sec, granting the first ally to touch it a barrier that absorbs 1840 damage for 10 sec.\n\nEach time you send out a protective sphere, gain an absorb shield for 2% of your maximum health.\n\nWhen an ally gains the absorb shield, you and that ally heal for [ 346 * (1 + Versatility)].\nMinor Power:\nUnwavering Ward\nEvery 10 sec, allies within 15 yds gain a shield that absorbs [ 113 * (1 + Versatility)] damage, stacking up to [ 848 * (1 + Versatility) * (1.2)].\n\nTargets protected by Unwavering Ward take 3% reduced damage.\n\nUnique: Corruption Resistance increased by 10." }
entries[168939] = { ["name"] = "Osmenite Shards", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Several small, unusable shards of osmenite.\"" }
entries[168940] = { ["name"] = "Ward of Unimaginable Brilliance", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Unwavering Ward.\nMajor Power:\nGuardian Shell\nChanneled (4 sec cast) 3 min cooldown Release 12 protective spheres outward over 4 sec, granting the first ally to touch it a barrier that absorbs 1840 damage for 10 sec.\n\nEach time you send out a protective sphere, gain an absorb shield for 2% of your maximum health.\n\nWhen an ally gains the absorb shield, you and that ally heal for [ 346 * (1 + Versatility)].\nMinor Power:\nUnwavering Ward\nEvery 10 sec, allies within 15 yds gain a shield that absorbs [ 113 * (1 + Versatility)] damage, stacking up to [ 848 * (1 + Versatility) * (1.2)].\n\nTargets protected by Unwavering Ward take 3% reduced damage.\n\nUnique: Corruption Resistance increased by 10." }
entries[168941] = { ["name"] = "Vitality Redistribution Lattice", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Vitality Conduit.\nMajor Power:\nVitality Conduit\n40 yd range Instant 1 min cooldown Direct the Vitality Conduit toward an ally. Every 0.5 sec for 6 sec, they transfer [ 958 * (1 + Versatility)] health from the highest-health ally within 30 yds.\nMinor Power:\nTransference\nApproximately 15 procs per minute Targets of your heals have a very high chance to transfer [ 958 * (1 + Versatility)] health from the highest-health ally within 30 yds." }
entries[168942] = { ["name"] = "Mesh of Expanding Vitality", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Vitality Conduit.\nMajor Power:\nVitality Conduit\n40 yd range Instant 45 sec cooldown Direct the Vitality Conduit toward an ally. Every 0.5 sec for 6 sec, they transfer [ 958 * 1.2 * (1 + Versatility)] health from the highest-health ally within 30 yds.\nMinor Power:\nTransference\nApproximately 15 procs per minute Targets of your heals have a very high chance to transfer [ 958 * 1.2 * (1 + Versatility)] health from the highest-health ally within 30 yds." }
entries[168943] = { ["name"] = "Grid of Bursting Vitality", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Vitality Conduit.\nLearn Rank 3 Condensed Life-Force, Vitality Conduit, or Azeroth's Undying Gift on another character to unlock this essence.\nMajor Power:\nVitality Conduit\n40 yd range Instant 45 sec cooldown Direct the Vitality Conduit toward an ally. Every 0.5 sec for 6 sec, they transfer [ 958 * 1.2 * (1 + Versatility)] health from the highest-health ally within 30 yds.\n\nIf the target reaches full health, jumps to the lowest-health nearby target for the remaining duration.\nMinor Power:\nTransference\nApproximately 15 procs per minute Targets of your heals have a very high chance to transfer [ 958 * 1.2 * (1 + Versatility)] health from the highest-health ally within 30 yds.\n\nHealth transfers leave a 575 damage absorb shield on the target for 5 sec." }
entries[168944] = { ["name"] = "Web of Unbridled Vitality", ["text"] = "Rank 4\nBinds when picked up\nUnique\nClasses: Paladin , Priest , Shaman , Monk , Druid , Evoker\nUse: Infuse your Heart of Azeroth with Vitality Conduit.\nMajor Power:\nVitality Conduit\n40 yd range Instant 45 sec cooldown Direct the Vitality Conduit toward an ally. Every 0.5 sec for 6 sec, they transfer [ 958 * 1.2 * (1 + Versatility)] health from the highest-health ally within 30 yds.\n\nIf the target reaches full health, jumps to the lowest-health nearby target for the remaining duration.\nMinor Power:\nTransference\nApproximately 15 procs per minute Targets of your heals have a very high chance to transfer [ 958 * 1.2 * (1 + Versatility)] health from the highest-health ally within 30 yds.\n\nHealth transfers leave a 575 damage absorb shield on the target for 5 sec." }
