entries[169194] = { ["name"] = "Snapback Scuttler", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Giant crabs are native to Nazjatar and a favored food of the naga. This one must have been well-kept to grow this large.\"\nAchievement:\nUndersea Usurper\nCategory:\nBattle for Azeroth" }
