entries[169198] = { ["name"] = "Royal Snapdragon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Captured at a young age and raised to serve naga hunters, snapdragons are loyal and fierce companions.\"\nDrop:\nAnkoan Supplies\nDrop:\nUnshackled Supplies" }
entries[169199] = { ["name"] = "Snapdragon Kelpstalker", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When a snapdragon bites you, the worry isn't about the bite itself, but the poison that will begin to eat away at the wound.\"\nQuest:\nGood Girl\nZone:\nNazjatar" }
entries[169200] = { ["name"] = "Deepcoral Snapdragon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The snapdragon is a quiet hunter in the water, but is far less stealthy on land.\"\nQuest:\nWild Tame\nZone:\nNazjatar" }
entries[169201] = { ["name"] = "Fabious", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount. Can only be used underwater.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"He emerges from the water, fins swaying lazily in the breeze, sun-kissed scales glittering. He is... Fabious.\"\nDrop:" }
entries[169202] = { ["name"] = "Crimson Tidestallion", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount. Can only be used underwater.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The blood-red coloration of these creatures is ideal for hiding in large coral formations.\"\nVendor:\nMrrl\nZone:\nNazjatar\nCost:\n4\n2\n1" }
