entries[169301] = { ["name"] = "Highborne Compendium of Swirling Tides", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: Your healing spells have a chance to grant an ally an absorption shield that absorbs up to 153 damage for 12 sec. While the shield is active, the targets Primary Stat is increased by 6 .\nSell Price:" }
entries[169302] = { ["name"] = "Highborne Compendium of Mystical Bulwark", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: When you take damage, you have a chance to heal for 78 health and gain 9 Armor for 10 sec, stacking up to ( 9 * 4) Armor.\nSell Price:" }
entries[169303] = { ["name"] = "Hell-Bent Bracers", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Flex, increasing arm power for 15 min. (45 Min Cooldown)\n\"Are you strong enough to wear them?\"\nSell Price:" }
entries[169304] = { ["name"] = "Leviathan's Lure", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: Your damaging abilities have a very low chance to summon a Leviathan, inflicting [ 165 * (1 + Versatility)] Physical damage to your target.\n\nDealing damage also cultivates luminous algae on your target, increasing your chance to summon.\nSell Price:" }
entries[169305] = { ["name"] = "Aquipotent Nautilus", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nUse: Unleash a wave that crashes into your target then returns to your original location, inflicting [ 24 * (5) * (1 + Versatility)] Frost damage over 4 sec to enemies in its path. Catch the wave to reduce the cooldown of this ability by 30 sec. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[169306] = { ["name"] = "Za'qul's Portal Key", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 10 Haste\nEquip: Your abilities have a low chance to create a Void Tear nearby for 30 sec. Moving to a Void Tear opens a portal for 10 sec. Standing in a portal grants you 28 Intellect.\nSell Price:" }
entries[169307] = { ["name"] = "Vision of Demise", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nUse: Reveal your enemy's impending demise, increasing your Haste by 30 for 10 sec. For every 10% health your target is missing, gain 4 additional Haste. (1 Min Cooldown)\nSell Price:" }
entries[169308] = { ["name"] = "Chain of Suffering", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nUse: Transfer 50% of your damage taken to an ally within 25 yards for 25 sec, up to 1644 damage. If your target moves out of range or falls below 25% health, the effect ends. (2 Min Cooldown)\nSell Price:" }
entries[169309] = { ["name"] = "Zoatroid Egg Sac", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: Casting a single target heal has a chance to summon a Zoatroid on your target, absorbing [ 76 * (1 + Versatility)] damage and granting up to 11 Versatility, based on the absorb remaining. Every 10% mana you spend nourishes your Zoatroids, adding [ 8 * (1 + Versatility)] absorb and 1 Versatility.\nSell Price:" }
entries[169310] = { ["name"] = "Bloodthirsty Urchin", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: 10% of damage taken grants you Healing Blood, up to [ 315 * (1 + Versatility)] total. Every 3 sec, [ 41 * (1 + Versatility)] Healing Blood is expended to heal you if you are injured.\nSell Price:" }
entries[169311] = { ["name"] = "Ashvane's Razor Coral", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nUse: Deal [ 25 * (1 + Versatility)] Physical damage and apply Razor Coral to your target, giving your damaging abilities against the target a high chance to deal [ 25 * (1 + Versatility)] Physical damage and add a stack of Razor Coral.\n\nReactivating this ability will remove Razor Coral from your target, granting you 3 Critical Strike per stack for 20 sec. (20 Sec Cooldown)\nSell Price:" }
entries[169312] = { ["name"] = "Luminous Jellyweed", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: Your heals have a chance to grant Luminescence to your most injured ally within 40 yds. Allies with Luminescence receive 10% additional healing, up to [ 87 * (1 + Versatility)] total additional healing.\nSell Price:" }
entries[169313] = { ["name"] = "Phial of the Arcane Tempest", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: Your damaging abilities have a low chance to surround you with an Arcane Tempest for 20 sec, inflicting 5 Arcane damage every 2 sec to nearby enemies. The Tempest accelerates each time it strikes a lone enemy, dealing damage more frequently.\nSell Price:" }
entries[169314] = { ["name"] = "Azshara's Font of Power", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 10 Critical Strike\nUse: Channel latent magic for up to 4 sec, increasing your primary stat by 30 . The duration is extended for each second spent channeling, up to 30 sec. (2 Min Cooldown)\nSell Price:" }
entries[169315] = { ["name"] = "Edicts of the Faithless", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: Every 40 seconds, gain an absorb that prevents [ 262 * (1 + Versatility)] Physical damage. If the absorb is consumed you gain Fanaticism, causing subsequent absorbs to prevent 10% more damage, up to 100%.\nUse: Declare Edict of the Sea Witch, causing this ability to instead absorb Magic damage and resetting Fanaticism. (40 Sec Cooldown)\nSell Price:" }
entries[169316] = { ["name"] = "Deferred Sentence", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: Defer [ 7 * (1 + Versatility)] healing every 3 seconds. Moving releases deferred healing, restoring health to your 3 most injured allies.\nSell Price:" }
entries[169317] = { ["name"] = "Enthraller's Bindstone", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 10 Versatility\nEquip: Your abilities have a chance to grant you 15 primary stat for 30 sec.\nSell Price:" }
