entries[169319] = { ["name"] = "Dribbling Inkpod", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: Your damaging abilities against enemies above 30% health have a very high chance to apply Conductive Ink. When an enemy falls below 30% health, Conductive Ink inflicts [ 26 * (1 + Versatility)] Nature damage per stack.\nSell Price:" }
